class Invalid(Exception):
    """Only fixed messages are exposed to certificate submitters."""


def load_config(path: Path | None = None) -> dict:
    if path is None:
        here = Path(__file__).resolve().parent
        path = here / "problem.toml"
        if not path.is_file():
            path = here.parent / "problem.toml"
    with open(path, "rb") as source:
        data = tomllib.load(source)
    params = data["params"]
    if (type(params["n"]) is not int or params["n"] != N
            or params["instance"] != INSTANCE
            or params["instance_sha256"] != INSTANCE_SHA256
            or type(data["max_certificate_bytes"]) is not int
            or data["max_certificate_bytes"] != MAX_CERTIFICATE_BYTES):
        raise ValueError("Fixed problem configuration mismatch")
    return {"n": N, "max_certificate_bytes": MAX_CERTIFICATE_BYTES}


def read_certificate(shot_dir: str | os.PathLike, limit: int) -> bytes:
    path = Path(shot_dir) / "certificate.json"
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_NONBLOCK", 0)
    try:
        fd = os.open(path, flags)
    except OSError:
        raise Invalid("Cannot read certificate.json as a regular file") from None
    with os.fdopen(fd, "rb") as source:
        info = os.fstat(source.fileno())
        if not stat.S_ISREG(info.st_mode):
            raise Invalid("certificate.json must be a regular file")
        if info.st_size > limit:
            raise Invalid("certificate.json exceeds 16384 bytes")
        raw = source.read(limit + 1)
    if len(raw) > limit:
        raise Invalid("certificate.json exceeds 16384 bytes")
    return raw


def check_depth(text: str) -> None:
    depth = 0
    in_string = escaped = False
    for ch in text:
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
        elif ch == '"':
            in_string = True
        elif ch in "[{":
            depth += 1
            if depth > MAX_DEPTH:
                raise Invalid("JSON nesting exceeds 2 container levels")
        elif ch in "]}":
            depth -= 1


def _no_float(_value: str):
    raise Invalid("Fractional and exponent-form numbers are not allowed")


def _no_constant(_value: str):
    raise Invalid("NaN and Infinity are not allowed")


def _bounded_int(value: str) -> int:
    if len(value.lstrip("-")) > MAX_INT_DIGITS:
        raise Invalid("Integer token exceeds 3 digits")
    return int(value)


def _unique_keys(pairs: list) -> dict:
    result = {}
    for key, value in pairs:
        if key in result:
            raise Invalid("Duplicate JSON object keys are not allowed")
        result[key] = value
    return result


def strict_json(raw: bytes):
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise Invalid("certificate.json must be UTF-8") from None
    check_depth(text)
    try:
        return json.loads(text, parse_float=_no_float, parse_int=_bounded_int,
                          parse_constant=_no_constant, object_pairs_hook=_unique_keys)
    except (ValueError, RecursionError):
        raise Invalid("certificate.json is not valid JSON") from None


@cache
def load_matrix() -> tuple:
    raw = zlib.decompress(base64.b64decode(DATA, validate=True))
    if len(raw) != INSTANCE_BYTES or hashlib.sha256(raw).hexdigest() != INSTANCE_SHA256:
        raise ValueError("Fixed instance checksum mismatch")
    tokens = raw.split()
    if len(tokens) != 1 + N * N or int(tokens[0]) != N:
        raise ValueError("Fixed instance dimensions mismatch")
    values = tuple(map(int, tokens[1:]))
    if min(values) < 0:
        raise ValueError("Fixed instance contains negative weights")
    return tuple(values[i * N:(i + 1) * N] for i in range(N))


def check_certificate(cert) -> tuple[int, dict]:
    if not isinstance(cert, dict) or set(cert) != {"order"}:
        raise Invalid("Top level must have exactly the key order")
    order = cert["order"]
    if not isinstance(order, list) or len(order) != N:
        raise Invalid("order must be a list of 500 integers")
    for vertex in order:
        if type(vertex) is not int or not 0 <= vertex < N:
            raise Invalid("order entries must be integers in 0..499")
    if len(set(order)) != N:
        raise Invalid("order must be a permutation of 0..499")
    matrix = load_matrix()
    score = 0
    for a in range(N):
        row = matrix[order[a]]
        for b in range(a + 1, N):
            score += row[order[b]]
    return score, {"order": order}


def canonical_hash(obj: dict) -> str:
    blob = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
    return hashlib.sha256(blob.encode("ascii")).hexdigest()


def verify_bytes(raw: bytes, cfg: dict) -> dict:
    if len(raw) > cfg["max_certificate_bytes"]:
        raise Invalid("certificate.json exceeds 16384 bytes")
    score, canon = check_certificate(strict_json(raw))
    return {"valid": True, "score": str(score),
            "canonical_hash": canonical_hash(canon), "message": "ok"}


def invalid(message: str) -> dict:
    return {"valid": False, "score": None, "canonical_hash": None, "message": message}


def verify_dir(shot_dir: str | os.PathLike, cfg: dict) -> dict:
    try:
        return verify_bytes(read_certificate(shot_dir, cfg["max_certificate_bytes"]), cfg)
    except Invalid as exc:
        return invalid(str(exc))
    except Exception:
        return invalid("Verification failed")


def emit(result: dict) -> None:
    line = json.dumps(result, ensure_ascii=True, separators=(",", ":"))
    sys.stdout.buffer.write(line.encode("ascii") + b"\n")
    sys.stdout.buffer.flush()


def main(argv: list[str]) -> int:
    if len(argv) != 2:
        emit(invalid("Usage: python verify.py <shot_dir>"))
        return 2
    try:
        cfg = load_config()
    except Exception:
        emit(invalid("Verifier configuration error"))
        return 2
    emit(verify_dir(argv[1], cfg))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
